function readJson(path, cb) {
  fs.readFile(path, 'utf8', (err, txt) => {
    if (err) return cb(err);
    try { cb(null, JSON.parse(txt)); } catch (e) { cb(e); }
  });
}

readJson('a.json', (err, a) => {
  if (err) throw err;
  readJson('b.json', (err, b) => {
    if (err) throw err;
    console.log(Object.assign({}, a, b));
  });
});
