Refactor this Go code to return errors instead of calling log.Fatal. Return the full file.

```
package main

import (
	"encoding/json"
	"log"
	"os"
)

type Config struct {
	Port int    `json:"port"`
	Host string `json:"host"`
}

func loadConfig(path string) Config {
	f, err := os.Open(path)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	var c Config
	if err := json.NewDecoder(f).Decode(&c); err != nil {
		log.Fatal(err)
	}
	return c
}

func main() {
	c := loadConfig("config.json")
	log.Printf("listening on %s:%d", c.Host, c.Port)
}
```

